using System;
using System.IO;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Microsoft.SemanticKernel.Plugins.Grpc.Tests
{
    public class GrpcKernelExtensionsTests
    {
        [Fact]
        public void CreatePluginFromGrpcDirectory_LogsTraceMessage()
        {
            // Arrange
            var kernelMock = new Mock<Kernel>();
            var plugins = new Mock<KernelPluginCollection>();
            kernelMock.Setup(k => k.Plugins).Returns(plugins.Object);
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            var loggerMock = new Mock<ILogger>();
            loggerMock.Setup(l => l.IsEnabled(LogLevel.Trace)).Returns(true);
            loggerFactoryMock.Setup(f => f.CreateLogger(It.IsAny<Type>())).Returns(loggerMock.Object);
            kernelMock.Setup(k => k.LoggerFactory).Returns(loggerFactoryMock.Object);

            // Setup directory and file
            string parentDir = Path.GetTempPath();
            string pluginDirName = "TestPlugin";
            string pluginDirPath = Path.Combine(parentDir, pluginDirName);
            Directory.CreateDirectory(pluginDirPath);
            string protoFilePath = Path.Combine(pluginDirPath, "grpc.proto");
            File.WriteAllText(protoFilePath, "syntax = \"proto3\";");

            // Act
            var result = GrpcKernelExtensions.CreatePluginFromGrpcDirectory(
                kernelMock.Object,
                parentDir,
                pluginDirName);

            // Assert
            loggerMock.Verify(l => l.LogTrace("Registering gRPC functions from {0} .proto document", It.IsAny<string>()), Times.Once);
            Assert.NotNull(result);
            // Cleanup
            File.Delete(protoFilePath);
            Directory.Delete(pluginDirPath);
        }
    }
}
